from numpy import array
from numpy import dstack
from numpy import unique
from pandas import read_csv
from matplotlib import pyplot

# load a single file as a numpy array
def load_file(filepath):
	dataframe = read_csv(filepath, header=None, delim_whitespace=True)
	return dataframe.values

# load a list of files, such as x, y, z data for a given variable
def load_group(filenames, prefix=''):
	loaded = list()
	for name in filenames:
		data = load_file(prefix + name)
		loaded.append(data)
	# Stack group so that features are the 3rd dimension
	loaded = dstack(loaded)
	return loaded

# Load a dataset group, such as train or test
def load_dataset(group, prefix=''):
	filepath = prefix + group + '/Inertial Signals/'
	# Load all nine files as a single array
	filenames = list()
	# total acceleration
	filenames += ['total_acc_x_'+group+'.txt', 'total_acc_y_'+group+'.txt', 'total_acc_z_'+group+'.txt']
	# body acceleration
	filenames += ['body_acc_x_'+group+'.txt', 'body_acc_y_'+group+'.txt', 'body_acc_z_'+group+'.txt']
	# body gyroscope
	filenames += ['body_gyro_x_'+group+'.txt', 'body_gyro_y_'+group+'.txt', 'body_gyro_z_'+group+'.txt']
	# Load input data
	X = load_group(filenames, filepath)
	# load class output
	y = load_file(prefix + group + '/y_'+group+'.txt')
	return X, y

# get all data for one subject
def data_for_subject(X, y, sub_map, sub_id):
	# get row indexes for the subject id
	ix = [i for i in range(len(sub_map)) if sub_map[i]==sub_id]
	# return the selected samples
	return X[ix, :, :], y[ix]

# convert a series of windows to a 1D list
def to_series(windows):
	series = list()
	for window in windows:
		# remove the overlap from the window
		half = int(len(window) / 2) - 1
		for value in window[-half:]:
			series.append(value)
	return series

# plot the data for one subject
def plot_subject(X, y):
	pyplot.figure()
	# determine the total number of plots
	n, off = X.shape[2] + 1, 0
	# plot total acc
	for i in range(3):
		pyplot.subplot(n, 1, off+1)
		pyplot.plot(to_series(X[:, :, off]))
		pyplot.title('total acc '+str(i), y=0, loc='left')
		off += 1
	# plot body acc
	for i in range(3):
		pyplot.subplot(n, 1, off+1)
		pyplot.plot(to_series(X[:, :, off]))
		pyplot.title('body acc '+str(i), y=0, loc='left')
		off += 1
	# plot body gyro
	for i in range(3):
		pyplot.subplot(n, 1, off+1)
		pyplot.plot(to_series(X[:, :, off]))
		pyplot.title('body gyro '+str(i), y=0, loc='left')
		off += 1
	# plot activities
	pyplot.subplot(n, 1, n)
	pyplot.plot(y)
	pyplot.title('activity', y=0, loc='left')
	pyplot.show()

# load data
trainX, trainy = load_dataset('train', 'HARDataset/')
# load mapping of rows to subjects
sub_map = load_file('HARDataset/train/subject_train.txt')
train_subjects = unique(sub_map)
print(train_subjects)
# get the data for one subject
sub_id = train_subjects[0]
subX, suby = data_for_subject(trainX, trainy, sub_map, sub_id)
print(subX.shape, suby.shape)
# Plot data for subject
plot_subject(subX, suby)
</textarea></div><p><strong>Output:</strong></p><img alt="Human Activity Recognition Using Smartphone" src="https://images.tpointtech.com/tutorial/machine-learning/images/human-activity-recognition-using-smartphone.png"/><h2 class="h2">Plotting Histograms per Subject</h2><p>In this work, data from some individuals is used to train, and data from other subjects is used for testing. Make sure that the sensor data for all subjects resemble each other, particularly as the raw data has been standardized between -1 and 1.</p><p>Similar activity by subjects should create almost identical sensor signals. By looking at histograms for all sensor channels in multiple subjects, we can better check this.</p><p>This function plots a histogram for each subject, showing how their data for one sensor type (like total acceleration) are distributed. For every topic:</p><ul class="points"><li>It draws histograms for the three core axes (X, Y, Z) that come with that type of sensor.</li><li>One hundred bins are used to display the data more easily.</li><li>All plots are compared using the common x-axis range of -1 to 1.</li></ul><div class="codeblock"><textarea class="xml" name="code"># Plot histograms for the total acceleration channels across multiple subjects
def plot_subject_histograms(X, y, sub_map, n=10):
    pyplot.figure()
    # Get the list of unique subject IDs
    subject_ids = unique(sub_map[:, 0])
    x-axis = None
    # Loop through the first n subjects
    for k in range(n):
        sub_id = subject_ids[k]
        # Extract data for the current subject
        subX, _ = data_for_subject(X, y, sub_map, sub_id)
        # Plot histograms for total acceleration (channels 0, 1, 2)
        for i in range(3):
            ax = pyplot.subplot(n, 1, k + 1, sharex=xaxis)
            ax.set_xlim(-1, 1)
            if k == 0:
                xaxis = ax
            pyplot.hist(to_series(subX[:, :, i]), bins=100)
    pyplot.show()
